INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('1fdf1134ab1234e0', 7, ' General Information
 About Rockwood Manufacturing Company
 Rockwood Manufacturing Company, founded in 1946 by the Gurzenda
 Family in rural southwestern Pennsylvania, focuses on the design and
 manufacture of quality builders’ hardware for commercial, institutional and
 finer residential buildings. Now in the third generation of skilled craftsman,
 we continue to develop new products and processes that improve our
 offering. Strict attention to detail from the selection of top-grade materials to
 the application of the finest finishes results in a tough, yet handsome product
 of the highest caliber.
Rockwood Manufacturing Co. founders,
brothers Norman and Vernon Gurzenda In 2008 Rockwood Manufacturing Company was purchased by
 ASSA ABLOY, the global leader in door opening solutions. This greatly
 expanded design and development capabilities and expanded the product
 offering to customers. This offering includes many coordinating products with
 other ASSA ABLOY Group companies through the Good Design Studio.


 Custom Designs
 Design your own hardware! Whether it is a modification of a standard
 product or a completely unique design, we will quote your design and offer
 suggestions for best mounting applications. We take special pride in our
 custom products. For more information, please contact our sales staff.




 Rockwood Architectural Door Pulls
 The alluring warmth of warm wood, smooth leather, clean and appealing
 lines. Just a few words to describe our beautiful architectural door pulls.
 With endless design options to choose from, our pulls will add contemporary
 beauty to any door opening.
 Refer to the Rockwood Architectural Door Pulls catalog, found on our web
 site at www.assaabloydooraccessories.us




 The Good Design Studio – your resource for beautiful doors, frames and
 hardware from ASSA ABLOY Group brands. Visit www.thegooddesignstudio.com
 to learn more.




 CORBIN RUSSWIN 107 McKINNEY 2 knuckle hinge ROCKWOOD
 and SARGENT ME lever with round end tips small door pull




 LEED Certification Contribution
 ASSA ABLOY can help to achieve prerequisites and accumulate points in several
 categories and credit areas of LEED. When you select a Rockwood stainless
 steel door pull for your LEED certified building project, you are using a product
ASSA ABLOY is a member of the USGBC
and CaGBC
 that is made from a minimum 75% post industrial waste and is 100% recyclable.
 Additionally these pulls can usually be refinished to their original appearance
U.S. Green Building Council logo is a
trademark owned by the U.S. Green Building any time in the life of the building, eliminating the need for replacement when a
Council and is used with permission. renovation is conducted. For further information, please call 1-800-458-2424 or
 refer to our website www.rockwoodmfg.com




800 458 2424 | www.rockwoodmfg.com
