INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('1fdf1134ab1234e0', 10, 'General Information
 Finish Tips
 Polished Brass
 Polished brass is a beautiful finish that does not normally weather very well
 outdoors. Rockwood products use a very durable baked on clear powder
 coat on most door pulls and push bars. In indoor usage, this finish
 is extremely durable.

 Stainless Steel
 Stainless steel is one of the most durable materials used in architecture;
 however there are many types with different properties and different levels
 of corrosion resistance. In most indoor (except chlorine and other harsh
 chemical exposure) and many outdoor (mildly corrosive) environments our
 standard stainless steel will perform exceeding well. It is best maintained
 by periodic water washing. If your job site has road salt, marine salt air,
 industrial, or urban pollution, we recommend the use of molybdenum
 bearing alloy 316 stainless steel. Specify US32316 or US32D316. To enhance
 the corrosion resistance of stainless steel, use the polished finish (US32) in
 place of the satin finish (US32D). Minute particles of dirt and debris can
 lodge in the microscopic crevices of the satin finish more readily than on
 a smooth surface promoting corrosion. The mirror smooth surface of the
 polished finish has no rough surface to retain microscopic dirt or debris.

 Heat Resistant
 Exterior hot sunny climates call for a finish that is resistant to heat. We
 recommend our white powder coat finish (WPC). This durable exterior finish
 reflects much of the heat rays and is substantially cooler to the touch than
 stainless steel or other finishes.

 Anti-Microbial Protection
 MicroShield® (US32DMS) is the ideal finish for hospitals, schools,
 laboratories, assisted living facilities, public restroom areas, and anywhere
 there is a concern to control bacteria growth for demanding standards of
 cleanliness. Contact our customer service department for more detailed
 information.

 Finish Sample Displays
 Educational and informative displays are available showing our most
 popular ­finishes.




 800 458 2424 | www.rockwoodmfg.com
 Check the web site for the up-to-date catalog
 Copyright © 2012-2024, ASSA ABLOY Accessories and Door Controls Group, Inc. All rights reserved. Reproduction in whole
 10 or in part without the express written permission of ASSA ABLOY Accessories and Door Controls Group, Inc. is prohibited.
