INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('1fdf1134ab1234e0', 11, 'How to Size Push Bars




 Rockwood Push and Pull Bar Mounting Details
Flush Doors
Door width:
 • Minus 5" for bent end bars
 • Minus 5" for square end post mount bars
 • Minus 7" for round end post mount bars
Stile and Rail Doors or Doors with Lites
Door width:
 • Minus width of one stile
CAUTION: Always confirm bars will not interfere with jamb
or cause pinching hazard.
CAUTION: On narrow stile doors, be sure push bar base fits
on the stile and bar does not interfere with the stop.




Handing of Doors
 Inside
The handing of a door is determined from the outside of
the opening.
Standing outside the door:
 Left Hand Outside Right Hand
 • If the hinges are on the right, it is a right hand door
 • If the hinges are on the left, it is a left hand door
 Inside
  • If the door opens away from you, it is a regular bevel door
  • If the door opens toward you, it is a reverse bevel door

 Outside

 Left Hand Right Hand
 Reverse Bevel Reverse Bevel




Mounting Types for Push Bars No. 10 through No. 45
and No. 50, No. 51, No. 52
