 Rockwood Series 47 Tubular Push Bars
The Rockwood T Series 1" diameter tubular push and pull bar sets are made from sturdy .065" thick wall tubing. Solid brass or
stainless steel inserts are brazed into the ends to provide a solid area for our guaranteed mounting systems.
Benefits of specifying the T Series push and pulls include:
 • Tubular pulls weigh 25% less than their solid counterparts; this 75% weight reduction greatly reduces the environmental impact
 of harvesting material for their manufacture – a LEED certified building goal
 • The lighter weight minimizes the risk of damage in shipping and handling
 • The cost of most tubular pulls represents a significant savings over the equivalent solid model
Considering all the benefits, the T Series pulls offer an improved value without any quality sacrifice.
T Series is also available in straight pulls (see page B15) and offset pulls (see page B29).




 T47 Series Tubular Push Bars
