INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('1fdf1134ab1234e0', 33, 'Location Standards




 Rockwood Push Plate Ordering Information
Positioning Applications: Sizing:
• Door pulls to plates • 11/4" standard cylinder hole cutout size
• Cutouts on plates • 3/8" diameter standard turn knob hole
• Engraving on plates • Other cutout sizes and styles are readily available
• Cutout and engraving on plates Engraving:
 • 1" high condensed block letters with black enamel fill
NOTE: Be sure the pull you choose will fit on the plate, • Other letter sizes and styles are readily available
allowing for cutouts and/or engraving


ADA Accessibility Guidelines for Buildings and Facilities (ADAAG)
As amended through 2004
4.13.9 Door Hardware. Handles, pulls, latches, locks, and other operating devices on accessible doors shall have a shape that
is easy to grasp with one hand and does not require tight grasping, tight pinching, or twisting of the wrist to operate. Lever-
operated mechanisms, push-type mechanisms, and U-shaped handles are acceptable designs. When sliding doors are fully
open, operating hardware shall be exposed and usable from both sides. Hardware required for accessible door passage shall
be mounted no higher than 48" (1220 mm) above finished floor.



Pull Positioning on
Plates 4" or Less in
Width




Pull Positioning on
Plates Wider than 4"
(Handing Required)




Recommended
Locations on Door




