INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('1fdf1134ab1234e0', 47, 'T Series 1" Tubular Pulls




 Rockwood Tubular Door Pulls
Rockwood T Series 1" diameter straight tubular pulls are made from sturdy .065" thick wall tubing. Solid brass or stainless
steel inserts are brazed into the ends to provide a solid area for our guaranteed mounting systems.
Benefits of specifying the T Series push and pulls include:
 • Tubular pulls weigh 25% less than their solid counterparts; this 75% weight reduction greatly reduces the environmental
 impact of harvesting material for their manufacture – a LEED certified building goal
 • The lighter weight minimizes the risk of damage in shipping and handling
 • The cost of most tubular pulls represents a significant savings over the equivalent solid model
Considering all the benefits, the T Series pulls offer an improved value without any quality sacrifice.
T Series is also available in offset pulls (see page B29) and in both Series 47 push bars and push & pull bar sets
(see pages A19-A21).




 Tubular Door Pulls No. T110, T111A, T111, T112, T118
 Material: Brass, bronze, stainless steel
 Finishes: Available in standard architectural finishes (see page 9)
 Fastener: 1/
 4 - 20 x 21/4" thru bolt & finish washer (standard 13/4" door)

 Options: • Back to back mounting in pairs — use BTB suffix and mounting
 type number (T112BTB5)
 • Concealed mounting single pulls — use C suffix and mounting
 type number (T112C6)
 • Advise if door thickness is other than 13/4"
 • See page B13 for mounting selection (standard duty 1/4 - 20)
 • 21/2" Barrier Free clearance — use BF prefix (TBF110)




 No. Material CTC Overall Base Pull Pull Clearance Clearance Weight
