INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('1fdf1134ab1234e0', 61, 'T Series 1" Tubular Pulls




 Rockwood Tubular Offset Door Pulls
The Rockwood T Series diameter offset tubular pulls are made from sturdy .065" thick wall tubing. Solid brass or stainless
steel inserts are brazed into the ends to provide a solid area for our guaranteed mounting systems.
Benefits of specifying the T Series push and pulls include:
 • Tubular pulls weigh 25% less than their solid counterparts; this 75% weight reduction greatly reduces the environmental
 impact of harvesting material for their manufacture – a LEED certified building goal
 • The lighter weight minimizes the risk of damage in shipping and handling
 • The cost of most tubular pulls represents a significant savings over the equivalent solid model
 Considering all the benefits, the T Series pulls offer an improved value without any quality sacrifice
 T Series is also available in straight pulls (see page B15) and in both Series 47 push bars and push & pull bar sets
 (see pages A19-A21).




 90˚ Offset Tubular Door Pulls
 No. TBF156, TBF157A, TBF157, TBF158, TBF159
 Material: Brass, bronze, stainless steel
 Finishes: Available in standard architectural finishes (see page 9)
 Fastener: 1/
 4 - 20 x 21/4" thru bolt & finish washer (standard 13/4" door)
 Features: Recommended for ADA openings
 Options: • Back to back mounting in pairs — use BTB suffix and mounting type
 number (TBF156BTB16)
 • Concealed mounting single pulls — use C suffix and mounting type
 number (TBF156C17)
 • Advise if door thickness is other than 13/4"
 • See page B27 for mounting selection (standard duty 1/4 - 20)


 No. Material Size CTC Overall Base Projection Clearance Offset Weight
