INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('1fdf1134ab1234e0', 85, 'Ordering Instructions



 Rockwood Door Edges
The use of door edges and armor plates not only offers superior protection to expensive doors, it also adds an attractive
and functional finishing touch. Armor plates and door edges are available in all architectural finishes. The following two
pages are intended to help you determine the cutout locations required on armor plates and door edges. Follow the steps
listed to assure complete consideration of all factors concerning cutout locations.

1. Determine the armor plate height. We recommend 48" high. If you cut holes for lock, make the armor plate high enough
 to provide at least 1/2" from edge of the top cutout to the top edge of the plate, or 1/2" above the top of the lock front when
 mortise lock is used. This prevents a cutout running out of the top edge of the plate.

2. Determine the armor plate width. Armor plates are usually mounted on the stop or push side of the door. Measure the
 net width of the door face and subtract the following depending on the type of door edges you specify:
 a) non-mortise door edges = 25/8" (for 1/8 gap)
 b) overlapping door edges = 2" (for 3/16" overlap)
 c) no door edges – single door = 11/4"
 d) no door edges – pairs of doors = 1" (without mullions)

3. List all hardware that will be mounted on the door. Identify those items that will require armor plate and/or door edge
 cutouts; i.e., lock spindle, cylinder, thumb piece, lock front and strike, flush bolts, hinges, louvers, lites.

4. Determine door undercut and location of armor plate and door edge to bottom of the door. We recommend mounting
 plates flush with the bottom of the door.

5. Determine location of all hardware cutout centerlines from the bottom of the armor plate.

6. Determine the backset of lock cutouts on the armor plate.
 Square Edge Bevel Edge
 a) with non-mortise door edges lock backset minus 1 5/16" 1 3 /8 "
 b) with overlapping door edges lock backset minus 1" 11/16"
 c) without door edges – single doors lock backset minus 5/
 8" 11/16"
 d) without door edges – pair of doors lock backset minus 3/
 8" 
 7/
 16 "

 (without mullions)

7. Specify the size of cutouts.

8. Determine the hand of the door. Armor plates are typically mounted on the stop or push side of the door.
 Function holes must be given special attention as they may not be required on reverse bevel doors.




 NOTE: Your door thickness
 is a nominal dimension.
 Doors can vary + or –
 1/16" from the nominal
 dimension. When ordering,
 verify actual door thickness
 to assure a working fit of
 the door edge.




