Rockwood Door Edge Worksheet
 This drawing shows typical location of cutouts on armor plates and door edges. It also illustrates non-mortise door edges,
 but this can be used as a guide for armor plates with overlapping door edges or no door edges. Use this as a worksheet
 to make your own drawings or photocopy and fill in your dimensions.
 For Hinge Cutouts: Be sure to allow for door undercut and location of edge on door if other than flush with bottom.
 For Lock Trim Protection: Consider using a trim protector bar (see pages C16-C20).




