INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('1fdf1134ab1234e0', 89, 'Solutions to Door and Trim Damage




 Rockwood Trim Protector Bars
Damage to doors and door trim (exit devices, knobs, levers, etc.) from hallway traffic such as carts and gurneys cost hospitals,
schools and other institutions tens of thousands of dollars every year. The following four pages are Rockwood Product''s line of
Unique, Patented Protection Products designed to prevent this damage. Made from solid stainless steel the line is engineered to
deflect traffic safely away from the door or trim.
Our line of trim protector bars is designed to safely deflect traffic away from exit devices, door knobs/levers, or other trim. These
bars are made from solid stainless steel and are available in both standard duty (3/16") and heavy duty (3/8") versions. The bars
are mounted either directly below, over, or in front of the trim depending on the application. They are available in a variety of
projections and center to centers to fit your needs. If you require custom designs our engineering department can work with you
to meet your needs.

Choosing the correct protection bar:
1. Determine traffic – light to moderate use = SD Series, heavy use = HD Series.
2. Measure projection – of exit device, door knob, etc.
3. Review product dimension – to match bar to your specific needs.



 Warning: Do not locate protection bars where they can impede operation of exit devices.




 How They Work

