INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('1fdf1134ab1234e0', 94, ' Vertical Rod Cover Application




Rockwood Vertical Rod/Latch Guard Covers
 Application shown
 The vertical rod cover (BFRC) is a sturdy channel made of .050"
 for products BFRC
 stainless steel (other finishes available) designed to fit over the vertical and BFLG. Protects
 rod, protecting it from damage caused by carts, gurneys, etc. It is vertical rod and latch
