INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('1fdf1134ab1234e0', 120, 'Rockwood Overhead Holders & Stops
 Introduction to Overhead Stops & Holders
 Rockwood Overhead Stops and Holders are used to extend the life of the door, frame and any door closing devices. They
 may be necessary if there are strong winds, high traffic or abuse.
 • When used in conjunction with a floor closer, you have absolute door control, top and bottom.
 • Provides positive deadstop at selected degree
 • There are 2 functions, 3 ways to order:
 Hold Open – door remains held open near deadstop location
 Stops – door deadstops at a particular degree of opening
 Multi Function – adaptable as hold open and/or stops
 • Available as surface mounted or concealed
 • Standard mount on push side of door (See model descriptions for pull side installations)
 • Thru bolts are furnished with all surface models and must be used for installation

 WARNING: HOLD OPEN FUNCTION CANNOT BE USED ON LABELED OPENINGS!

 Shock Block Hold Open Spring
 To Convert from Hold Open to Stop Function:
 1. Remove the plastic end cap (#1) at the spring end of the channel. Block Plate
 2. With 3/16" hex key wrench, loosen the set
 screw in shock block.
 3. Remove the shock block plate and
 the hold open spring from channel.
 4. Remove the hold open spring from the shock block.
 5. Replace the shock block and block plate into channel.
 6. Replace the plastic end cap. Shock Block Shock Spring Slider Cam

 7. Install unit on door.
 8. Adjust to desired opening and
 tighten set screw.
 To Select Degree of Stop
 Plastic End Set Screw
 (Hold Open Models): Cap #1 Plastic End
 Cap #2
 1. Engage door in hold open position.
 Arm
 2. Using a 3/16" hex wrench, loosen the set screw in the shock block.
 3. Open door to desired degree of opening.
 4. Tighten set screw.
 5. Verify door opening position and re-adjust, if needed.




 800 458 2424 | www.rockwoodmfg.com
 Check the web site for the up-to-date catalog
 Copyright © 2012-2024, ASSA ABLOY Accessories and Door Controls Group, Inc. All rights reserved. Reproduction in whole
 D20 or in part without the express written permission of ASSA ABLOY Accessories and Door Controls Group, Inc. is prohibited.
