INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('1fdf1134ab1234e0', 135, ' Rockwood 2600 Series Door Coordinators
Door Coordinators No. 2600 Series
Material: Steel
Finishes: Black, US28
Fastener: 7 ea. #12 - 24 x 11/4 TH type C tapping screws
Size: Standard device size 5/8" x 1 5/8" x 52"
Features: Non-handed. Override protection to prevent damage in case of abnormal force on door
 Mechanism and filler bar completely fill width of opening and when painted to match frame
 it becomes virtually invisible
Ordering: Stock Sizes

 No. Opening Weight
 2660 60" 7.0 lbs.
 2672 72" 8.0 lbs.
 2696 96" 9.75 lbs.

 Custom Sizes — The 2600 Series coordinators are manufactured in different housing lengths to coordinate
 the full range of door sizes:
 • NX2600 Series: For jamb opening widths (A + B dimension) from 48" - 54". E dimension, 42"
 • 2600 Series: For jamb opening widths (A + B dimension) from 54" - 96". E dimension, 52"
 Determining Coordinator Item Number
 • Active door widths A plus inactive door width B equals the last two or three digits of all 2600 Series
 coordinator item numbers (2680 is for 80" door opening)
 • Less than 48" jamb widths = N2600 Series (N2644 = 44" opening).
 • Larger sizes are available (L, XL). Contact the factory

 NOTE: 2600 Series Coordinators are designed so that surface vertical rod strike preps can be made directly
 into the coordinator body.

 No. Jamb Widths Coordinator Length
 NX2648- NX2654 48"-54" 42"
 2655 - 2660 55" - 60" 52"
 2661 - 2672 61" - 72" 52"
 2673 - 2696 73" - 96" 52"

