 Automatic Flush Bolts No. 2840 (Automatic Top Bolt Only)
 No. 2842 (Set) (replaces the No. 1840 and No. 1842)
 Material: Brass, stainless steel
 Finishes: US3, US4, US10, US10B, 10BE, US26, US26D, US32D
 Fastener: No. 2842: 20 ea. #8 x 3/4" FH combo screws, 2 ea. #6 - 8 plastic anchors
 No. 2840: 10 ea. #8 x 3/4" FH combo screws. NOTE: No plastic anchor required for top only
 Features: • For Fire Rated Metal Doors labeled A, B, C, D & E up to 4''w x 8''h
 • Non-handed
 • Fully automatic– opening active door retracts top and bottom bolts
 • Override feature prevents damage to doors or bolts if bolt heads are blocked from
 entering strikes
 • Bolt head rods are adjustable up to 11/2"
 • Thermal lock automatically locks the inactive door under high heat conditions due to fire
