INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('1fdf1134ab1234e0', 142, 'Rockwood Automatic Flush Bolts
 Automatic Flush Bolt with Bottom Fire Bolt
 No. 2960 (replaces 1960)
 Material: Brass, Stainless Steel
 Finishes: US3, US4, US10, 10BE, US32D, US32, BSP
 Fastener: 4 ea. #8 x 1" FH SMS, 4 ea. #8 x 3/4" FH combo screws, 2 ea. plastic anchors
 Features: • For Fire Rated Wood Core & Composite Doors
 • Durable, tested over 1 million cycles
 • Smaller profile adds stability to the door
 • Only two 11/8" diameter holes for easier door preparation
 • Preparation prevents the veneer from splitting at the corners of the door
 • Quiet & smooth activation
 • Fully automatic—opening active door retracts top bolt
 • Non-handed.
 • Override feature prevents damage to doors or bolt if bolt head is blocked
 from entering strike
 • Low (3 lbs. maximum) closing force. ADA Compliant
 • Adjustable bolt head rod: bolts can be vertically adjusted 1/2" for unusual clearances
 • For up to 4'' w x 9'' h fire rated wood core & composite doors up to
 20 minutes fire rating.

 No. Face Plate Size Weight
 2960 1 8" x 2 4"
