INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('1fdf1134ab1234e0', 149, ' BF Series ADA Signs




 Rockwood Tactile Signage - With Braille
 Material: .125" non-glare plastic or .050" brass, bronze
 Finishes: Plastic signs: available in black, blue, brown, or red with standard 1"
 white lettering
 Metal signs: available in standard architectural finishes (see page 9)
 Fastener: 4 ea. #6 x 5/8" OH SMS
 Size: 8" x 8"
 Ordering: Specify background finish along with any options
 Features: Plastic signs:
 • Raised characters and Grade 2 Braille translation
 • Meets ADAAG Section 4.30 requirements
 Metal signs:
 • Raised black lettering and Grade 2 Braille translation.
 • Attractive architectural finishes
 Options: • SA – self-adhesive mounting




 No. BF683 No. BF684 No. BF685 No. BF686




 No. BF687 No. BF688 No. BF689




Recommended Mounting Location for Signs
Excerpts from ADA Accessibility Guidelines for Buildings
and Facilities (ADAAG). RESTROOM


4.30.6 Mounting Location and Height: Where permanent identification is
provided for rooms and spaces, signs shall be installed on the wall adjacent
to the latch side of the door. Where there is no wall space to the latch side of
the door, including at double leaf doors, signs shall be placed on the nearest
adjacent wall. Mounting height shall be 60" (1525 mm) above the finish floor to 60"
the centerline of the sign. Mounting location for such signage shall be so that
a person may approach within 3" (76 mm) of signage without encountering
protruding objects or standing within the swing of a door.




